import java.util.*;

class Solution {
    public List<Integer> safeNodes(int[][] graph) {
        int n = graph.length;
        List<List<Integer>> rev = new ArrayList<>();
        for (int i = 0; i < n; i++) rev.add(new ArrayList<>());
        int[] out = new int[n];
        for (int v = 0; v < n; v++) {
            out[v] = graph[v].length;
            for (int u : graph[v]) rev.get(u).add(v); // reverse the edge
        }
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int v = 0; v < n; v++) if (out[v] == 0) q.add(v); // terminals are safe
        boolean[] safe = new boolean[n];
        while (!q.isEmpty()) {
            int u = q.poll();
            safe[u] = true;
            for (int v : rev.get(u))
                if (--out[v] == 0) q.add(v); // all of v's exits are safe now
        }
        List<Integer> res = new ArrayList<>();
        for (int v = 0; v < n; v++) if (safe[v]) res.add(v);
        return res;
    }
}

