class Solution:
    def safeNodes(self, graph: List[List[int]]) -> List[int]:
        n = len(graph); rev = [[] for _ in range(n)]; out = [len(g) for g in graph]
        for v in range(n):
            for u in graph[v]: rev[u].append(v)
        q = deque(v for v in range(n) if out[v] == 0); safe = [False] * n
        while q:
            u = q.popleft(); safe[u] = True
            for v in rev[u]:
                out[v] -= 1
                if out[v] == 0: q.append(v)
        return [v for v in range(n) if safe[v]]

