function safeNodes(graph) {
  const n = graph.length, color = new Array(n).fill(0);
  for (let s = 0; s < n; s++) {
    if (color[s]) continue;
    const st = [[s, 0]]; color[s] = 1;
    while (st.length) {
      const top = st[st.length - 1], v = top[0];
      if (top[1] < graph[v].length) {
        const u = graph[v][top[1]++];
        if (color[u] === 0) { color[u] = 1; st.push([u, 0]); }
        else if (color[u] === 1 || color[u] === 3) { color[v] = 3; }
      } else {
        st.pop(); if (color[v] !== 3) color[v] = 2;
        if (st.length && color[v] === 3) color[st[st.length - 1][0]] = 3;
      }
    }
  }
  const res = []; for (let v = 0; v < n; v++) if (color[v] === 2) res.push(v); return res;
}
